import assert from 'node:assert/strict';
import { createRecordRepository } from './src/record-repository.js';
import { createDetailWorkspace } from './src/workspace.js';

function makeTransport() {
  const listeners = new Map();
  let subscriptions = 0;
  let stops = 0;
  return {
    subscribe(id, receive) {
      subscriptions++;
      const set = listeners.get(id) ?? new Set();
      listeners.set(id, set);
      set.add(receive);
      return () => { stops++; set.delete(receive); };
    },
    emit(id, value) { for (const receive of listeners.get(id) ?? []) receive(value); },
    get subscriptions() { return subscriptions; },
    get stops() { return stops; },
  };
}

const warmTransport = makeTransport();
const warmDetails = [];
const warmSelections = [];
const warm = createDetailWorkspace({
  repository: createRecordRepository({ transport: warmTransport, seed: { a: 'cached' } }),
  renderSelection: id => warmSelections.push(id),
  renderDetail: record => warmDetails.push(record),
});
warm.open('a');
assert.deepEqual(warmDetails, [{ id: 'a', value: 'cached', source: 'cache' }]);
assert.equal(warm.selection(), 'a');
assert.equal(warmTransport.subscriptions, 1);
warmTransport.emit('a', 'fresh');
assert.deepEqual(warmDetails.at(-1), { id: 'a', value: 'fresh', source: 'network' });
warm.open('a');
assert.equal(warmTransport.stops, 1);
assert.equal(warmTransport.subscriptions, 2);
warm.close();
assert.equal(warmTransport.stops, 2);
assert.deepEqual(warmSelections, [null, 'a', null, 'a', null]);

const coldTransport = makeTransport();
const coldDetails = [];
const cold = createDetailWorkspace({
  repository: createRecordRepository({ transport: coldTransport }),
  renderSelection() {}, renderDetail: record => coldDetails.push(record),
});
cold.open('b');
assert.deepEqual(coldDetails, []);
coldTransport.emit('b', 'network');
assert.deepEqual(coldDetails, [{ id: 'b', value: 'network', source: 'network' }]);

const reentrantTransport = makeTransport();
let reentrant;
const reentrantWorkspace = createDetailWorkspace({
  repository: createRecordRepository({ transport: reentrantTransport, seed: { a: 1 } }),
  renderSelection() {},
  renderDetail() {},
  onDetail(record, navigation) { if (record.id === 'a') navigation.open('b'); },
});
reentrantWorkspace.open('a');
assert.equal(reentrantWorkspace.selection(), 'b');
assert.equal(reentrantTransport.subscriptions, 2);
assert.equal(reentrantTransport.stops, 1);
console.log('detail activation checks passed');
EOF
